<?php
require __DIR__.'/../app/core.php';require ROOT.'/app/posts.php';
$installed=(int)db()->query('SELECT count(*) FROM admins')->fetchColumn()>0;$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    csrf();$action=$_POST['action']??'';
    try {
        if($action==='logout'){session_destroy();header('Location: admin.php');exit;}
        $ip=hash('sha256',$_SERVER['REMOTE_ADDR']??'local');$q=db()->prepare('SELECT * FROM attempts WHERE ip=?');$q->execute([$ip]);$attempt=$q->fetch();
        if($attempt&&$attempt['hits']>=8&&$attempt['started']>time()-900)throw new RuntimeException('Terlalu banyak percobaan. Coba lagi dalam 15 menit.');
        db()->prepare('DELETE FROM attempts WHERE started < ?')->execute([time()-900]);
        db()->prepare('INSERT INTO attempts VALUES(?,1,?) ON CONFLICT(ip) DO UPDATE SET hits=hits+1')->execute([$ip,time()]);
        $username=trim((string)($_POST['username']??''));$password=(string)($_POST['password']??'');
        if(!$installed&&$action==='setup'){
            $token=(string)($config['setup_token']??'');if(strlen($token)<24||str_starts_with($token,'GANTI_')||!hash_equals($token,(string)($_POST['token']??'')))throw new RuntimeException('Isi setup_token acak di config.php, lalu masukkan token yang sama di sini.');
            if(!preg_match('/^[a-zA-Z0-9_.-]{3,40}$/',$username)||strlen($password)<12||strlen($password)>200)throw new RuntimeException('Username 3–40 karakter; password 12–200 karakter.');
            db()->prepare('INSERT INTO admins(id,username,password) VALUES(1,?,?)')->execute([$username,password_hash($password,PASSWORD_DEFAULT)]);$installed=true;$_SESSION['admin']=1;
        }elseif($installed&&$action==='login'){
            $q=db()->prepare('SELECT * FROM admins WHERE username=?');$q->execute([$username]);$admin=$q->fetch();
            if(!$admin||!password_verify($password,$admin['password']))throw new RuntimeException('Username atau password salah.');$_SESSION['admin']=$admin['id'];
        }else throw new RuntimeException('Permintaan tidak valid.');
        db()->prepare('DELETE FROM attempts WHERE ip=?')->execute([$ip]);session_regenerate_id(true);$_SESSION['last_active']=time();header('Location: admin.php');exit;
    }catch(Throwable $e){$error=$e instanceof PDOException?'Setup gagal. Periksa apakah admin sudah dibuat.':$e->getMessage();}
}
if(!empty($_SESSION['admin'])&&time()-(int)($_SESSION['last_active']??0)>14400)unset($_SESSION['admin']);
$logged=!empty($_SESSION['admin']);$site=settings();
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="csrf" content="<?=h($_SESSION['csrf'])?>"><title>Studio · <?=h($site['site_name'])?></title><link rel="stylesheet" href="assets/style.css?v=12"></head><body class="admin-body">
<?php if(!$logged):?>
<main class="login card"><a class="brand" href="index.php"><span class="brand-mark">▶</span> <?=h($site['site_name'])?><small>STUDIO</small></a><p class="eyebrow">RUANG KREATOR</p><h1><?=$installed?'Selamat datang kembali.':'Siapkan studio abang.'?></h1><p class="muted"><?=$installed?'Masuk untuk mengelola video dan iklan.':'Buat satu akun admin. SQLite disiapkan otomatis.'?></p>
<?php if($error):?><p class="notice error" role="alert"><?=h($error)?></p><?php endif;?>
<form method="post"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input type="hidden" name="action" value="<?=$installed?'login':'setup'?>">
<?php if(!$installed):?><label>Token pemasangan<input type="password" name="token" required autocomplete="off"></label><p class="hint">Salin config.example.php menjadi config.php dan ubah setup_token. Document root harus folder public.</p><?php endif;?>
<label>Username<input name="username" required autocomplete="username" maxlength="40"></label><label>Password<input type="password" name="password" required minlength="<?=$installed?1:12?>" maxlength="200" autocomplete="<?=$installed?'current-password':'new-password'?>"></label><button class="primary wide"><?=$installed?'Masuk ke studio':'Buat akun & mulai'?> <span>→</span></button></form></main>
<?php else:
$videos=db()->query('SELECT * FROM videos ORDER BY created_at DESC')->fetchAll();$r2=setting('r2',[]);
$folders=listFolders();$byId=array_column($videos,null,'id');$inFolder=folderedIds();$loose=array_filter($videos,fn($v)=>!isset($inFolder[$v['id']]));
